Given the root of a Binary Tree, find the maximum and minimum element present in the tree.Examples:Input: root[] = [2, 7, 5, N, 6, N, 9, 1, 11, 4] Output: 11 1Explanation: The maximum and minimum element in this binary tree is 11 and 1 respectively.Input: root[] = [6, 5, 8, 2] Output: 8 2Explanation: The maximum and minimum element in this binary tree is 8 and 2 respectively.Try It YourselfTable of ContentRecursive Traversal with Current Maximum/Minimum - O(n) Time and O(h) SpaceRecursive Divide and Conquer - O(n) Time and O(h) SpaceRecursive Traversal with Current Maximum/Minimum - O(n) Time and O(h) SpaceThe idea is to traverse the binary tree recursively and keep updating the current maximum and minimum values whenever a node is visited.Working of Approach:Initialize maximum as INT_MIN and minimum as INT_MAX.Traverse the binary tree using DFS.Update the maximum and minimum using the current node's value.Continue the traversal for the left and right subtrees.After the traversal, return the final maximum and minimum values.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Structure of a Binary Tree Node
class Node
{
  public:
    int data;
    Node *left;
    Node *right;

    Node(int x)
    {
        data = x;
        left = right = nullptr;
    }
};

// DFS traversal to update maximum and minimum values
void dfs(Node *root, int &mx, int &mn)
{

    // Base Case
    if (root == nullptr)
        return;

    // Update maximum and minimum values
    mx = max(mx, root->data);
    mn = min(mn, root->data);

    // Recur for left and right subtrees
    dfs(root->left, mx, mn);
    dfs(root->right, mx, mn);
}

// Function to find the maximum element
int findMax(Node *root)
{
    int mx = INT_MIN;
    int mn = INT_MAX;

    dfs(root, mx, mn);

    return mx;
}

// Function to find the minimum element
int findMin(Node *root)
{
    int mx = INT_MIN;
    int mn = INT_MAX;

    dfs(root, mx, mn);

    return mn;
}

int main()
{

    // Construct the binary tree
    //        6
    //      /   \
    //     5     8
    //    /
    //   2

    Node *root = new Node(6);
    root->left = new Node(5);
    root->right = new Node(8);
    root->left->left = new Node(2);

    cout << findMax(root) << " ";
    cout << findMin(root);

    return 0;
}


